  for (let i = 0; i < 30; i++) { const x = rand(-120, 120), z = rand(-120, 120); if (plainsClear(x, z)) continue; if (!covers.some(c => Math.hypot(c.x - x, c.z - z) < c.r + 2) && Math.hypot(x, z) > 6) rock(x, z, rand(0.4, 1.4)); }
