  e.state = 'idle'; e.passive = true; e.tgt = null; e.keiSlot = slot;
  if (other) { K.side = e.team; K.phase = 'go'; mechSay(e, 'cata'); MECH.log.push('cata:' + e.team); }
  if (body) { keiBloodSay(e); vehDumpBodies(K); }
