    const k = i / n, z = zFoot + (zTop - zFoot) * k, y = 0.5 + (yTop - 0.1) * k;
    const rung = new THREE.Mesh(new THREE.BoxGeometry(0.96, 0.08, 0.14), WOOD_L);
    rung.position.set(x, y, z); g.add(rung);
