      const spd = C.phase === 'flee' && Math.abs(fleeDiff) > 1.05 ? Math.min(Math.max(C.v, 0), 0.9) : C.v;
      const nx = C.x + Math.sin(yaw2) * spd * dt, nz = C.z + Math.cos(yaw2) * spd * dt;
