      const ep = e.s.position, t = clamp(((ep.x - p0.x) * sx + (ep.z - p0.z) * sz) / sl, 0, 1), cx = p0.x + sx * t, cz = p0.z + sz * t, y = p0.y + (p1.y - p0.y) * t - e.baseY;
