const MTN = { on: false, phase: 0, gates: [], pits: [], traps: [], needles: [], doors: [], stones: [], posts: [[], [], []], hold: [], garrison: false, slowT: 0, volley: false, won: false, spawnI: 0, bar: null, entered: false };
