  for (let i = 0; i <= N; i++) { const x = xa + (xb - xa) * i / N; pts.push([x, Math.max(0.2, ukW(x, y) - inset)]); }
  sh.moveTo(pts[0][0], -pts[0][1]); for (const [x, w] of pts) sh.lineTo(x, -w); for (let i = N; i >= 0; i--) sh.lineTo(pts[i][0], pts[i][1]);
