  for (const s of [-1, 1]) { const r = new THREE.Mesh(new THREE.BoxGeometry(w + 0.9, 0.14, sl), M.roof); r.position.set(0, h + Math.tan(a) * half / 2 - 0.05, s * half / 2); r.rotation.x = s * a; r.castShadow = true; g.add(r); }
