  const r = Math.min(w, d) / 2, n = Math.max(1, Math.ceil(Math.max(w, d) / r) - 1);   // NPC の当たり：足元の円を並べる
  for (let i = 0; i <= n; i++) { const k = n ? i / n : 0.5; colliders.push(w >= d ? { x: B.x0 + r + (w - 2 * r) * k, z, r: r * 1.08 } : { x, z: B.z0 + r + (d - 2 * r) * k, r: r * 1.08 }); }
