      B.quad(k, v[2], v[1], v[5], v[6], tile); B.quad(k, v[0], v[3], v[7], v[4], tile); B.quad(k, v[7], v[6], v[5], v[4], tile);
      B.quad(k, v[3], v[2], v[6], v[7], tile); B.quad(k, v[1], v[0], v[4], v[5], tile);
