  for (const b of UK3.beams) { if (b.lamp.visible) lamps.push([b.lamp.position.x, b.lamp.position.y - 1.4, b.lamp.position.z, 5.5, 0.9]); if (b.pool.visible) lamps.push([b.P.x, 0, b.P.z, b.R * 1.15, 1.25]); }
