  { const V = PAL.doors.find(d => d.visit && !d.R.allowed && Math.hypot(player.pos.x - d.x, player.pos.z - d.z) < 2.4); if (V) return dry ? V.R.name + 'をノックする（E）' : palVisitKnock(V); }
