    if (!host && PAL.named[own]) { ukDlg([{ say: 'k_knock' }, { fn: () => popup('（返事がない。' + (UK_WHO_NAME[own] || '部屋の主') + 'は別の部屋にいるようだ）') }]); PAL.log.push('visit:away'); return; }
