  const M = V[UK2.on || UK3.on || UK4.on ? 'r' : 'm'], pk = a => a && a.length ? a[(Math.random() * a.length) | 0] : null;
  const sumiE = (UK4.on && UK4.sumi) || (UK3.on && UK3.sumi) || sec.e, seq = [['殿', pk(M.king), null]];
